create_post.beforeRequest:
var t = request.body.tiptap_body_json, b = { space_id: request.body.space_id, name: inputs.name };
if (t && typeof t === 'object' && t.body) b.tiptap_body = t;
else if (inputs.text_body || !t) b.tiptap_body = { body: { type: 'doc', content: [{ type: 'paragraph', content: [{ type: 'text', text: inputs.text_body || '' }] }] } };
else throw new Error("Invalid body input. Provide either 'Post Body (Plain Text)' or a valid 'Tiptap Body JSON'. If both are empty, an empty post will be created.");
b.status = inputs.status || 'published';
if (inputs.published_at && b.status === 'scheduled') b.published_at = new Date(inputs.published_at).toISOString();
if ('is_comments_enabled' in request.body) { b.is_comments_enabled = request.body.is_comments_enabled; b.is_comments_closed = !b.is_comments_enabled; }
if ('skip_notifications' in request.body) b.skip_notifications = request.body.skip_notifications;
if (inputs.user_email) b.user_email = inputs.user_email;
request.body = b;
return request;
